$ErrorActionPreference='Stop'
[Console]::OutputEncoding=[Text.Encoding]::UTF8
Set-Location $PSScriptRoot
$destination=Join-Path $PSScriptRoot 'dist'
$runtime='C:\Windows\Microsoft.NET\Framework64\v4.0.30319'
$compiler=Join-Path $runtime 'csc.exe'
if(-not (Test-Path $compiler)){throw 'Windows x64 .NET Framework compiler is required.'}
New-Item (Join-Path $destination 'network-limit') -ItemType Directory -Force|Out-Null
$references=@('/r:System.Windows.Forms.dll','/r:System.Drawing.dll','/r:System.Xaml.dll','/r:System.Web.Extensions.dll','/r:System.Security.dll',"/r:$runtime\WPF\WindowsBase.dll","/r:$runtime\WPF\PresentationCore.dll","/r:$runtime\WPF\PresentationFramework.dll")
$helper=Join-Path $destination 'network-limit\ConanBandwidth.exe'
& $compiler /nologo /codepage:65001 /target:winexe /platform:x64 /define:LIMITER_HELPER /optimize+ "/out:$helper" src\DownloadLimiter.cs network-limit\ConanBandwidth.cs
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
$helperHash=(Get-FileHash $helper -Algorithm SHA256).Hash.ToLowerInvariant()
$dllHash='c1e060ee19444a259b2162f8af0f3fe8c4428a1c6f694dce20de194ac8d7d9a2'
$driverHash='8da085332782708d8767bcace5327a6ec7283c17cfb85e40b03cd2323a90ddc2'
$hashSource="// Generated by the public source build.`ninternal static class LimiterHashes {`n internal const string Helper=`"$helperHash`";`n internal const string Dll=`"$dllHash`";`n internal const string Driver=`"$driverHash`";`n}`n"
[IO.File]::WriteAllText((Join-Path $PWD 'src\LimiterHashes.cs'),$hashSource,(New-Object Text.UTF8Encoding($false)))
& $compiler /nologo /codepage:65001 /target:winexe /platform:x64 /optimize+ "/out:$destination\ConanPet.exe" /win32manifest:app.manifest /resource:src\LimiterBootstrap.ps1,Conan.LimiterBootstrap /resource:src\SensorProviderHashes.json,Conan.SensorProviderHashes /resource:src\SensorBootstrap.ps1,Conan.SensorBootstrap $references @(Get-ChildItem src -Recurse -Filter '*.cs'|Sort-Object FullName|ForEach-Object{$_.FullName})
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
New-Item (Join-Path $destination 'bridge') -ItemType Directory -Force|Out-Null
Get-ChildItem bridge -File|Where-Object{$_.Extension -in @('.py','.ps1')}|Copy-Item -Destination (Join-Path $destination 'bridge')
& $compiler /nologo /codepage:65001 /target:exe /platform:x64 "/out:$destination\bridge\ConanBridge.exe" /r:System.Web.Extensions.dll src\AssistantLogic.cs src\CodexSessionTitles.cs bridge\ConanBridge.cs
if($LASTEXITCODE -ne 0){exit $LASTEXITCODE}
Write-Output 'Source compilation completed. Supply your own compatible atlas and optional dependencies before running.'
